export async function postKitchenTicket(body: string) {
   const response = await fetch('/api/kitchen/tickets', { method: 'POST', body });
   return response.json();
 }
 export async function readKitchenTicket(id: string) {
   return fetch('/api/kitchen/tickets/' + encodeURIComponent(id));
 }
